  if (!S.player.aboard) return false;
  const z = zoneAt(S.player.ly);
  return !!(z && z.type === type);
}
function canOpenBuild(){
  // The first workshop must be constructible before there is a workshop to stand in.
  return S.player.aboard && (nCarts('workshop') === 0 || inZone('workshop'));
}
function canBuildType(type){
  if (!S.player.aboard) return false;
  if (nCarts('workshop') === 0) return type === 'workshop';
  return inZone('workshop');
}

